function formatLastSeenStatus(lastSeen, isOnline) {
	if (!lastSeen) return isOnline ? {
		isOnline: true,
		statusText: "Online"
	} : {
		isOnline: false,
		statusText: "Offline"
	};
	const lastSeenDate = new Date(lastSeen);
	const now = /* @__PURE__ */ new Date();
	const diffMs = now.getTime() - lastSeenDate.getTime();
	const diffSec = Math.floor(diffMs / 1e3);
	const diffMin = Math.floor(diffSec / 60);
	const diffHours = Math.floor(diffMin / 60);
	if (isOnline && diffMin < 2) return {
		isOnline: true,
		statusText: "Online"
	};
	if (diffMin < 1) return {
		isOnline: false,
		statusText: "Active just now"
	};
	if (diffMin < 60) return {
		isOnline: false,
		statusText: `Active ${diffMin}m ago`
	};
	if (diffHours < 24) return {
		isOnline: false,
		statusText: `Active ${diffHours}h ago`
	};
	const isYesterday = now.getDate() - lastSeenDate.getDate() === 1 && now.getMonth() === lastSeenDate.getMonth() && now.getFullYear() === lastSeenDate.getFullYear();
	const timeStr = lastSeenDate.toLocaleTimeString([], {
		hour: "2-digit",
		minute: "2-digit"
	});
	if (isYesterday) return {
		isOnline: false,
		statusText: `Last seen yesterday at ${timeStr}`
	};
	return {
		isOnline: false,
		statusText: `Last seen ${lastSeenDate.toLocaleDateString([], {
			month: "short",
			day: "numeric"
		})} at ${timeStr}`
	};
}
