// src/utils/audioEffects.ts
var SoundEffects = class {
	constructor() {
		this.ctx = null;
	}
	getContext() {
		if (typeof window === "undefined") return null;
		if (!this.ctx) {
			const AudioCtx = window.AudioContext || window.webkitAudioContext;
			if (AudioCtx) this.ctx = new AudioCtx();
		}
		if (this.ctx && this.ctx.state === "suspended") this.ctx.resume().catch(() => {});
		return this.ctx;
	}
	playMessageSent() {
		try {
			const ctx = this.getContext();
			if (!ctx) return;
			const osc = ctx.createOscillator();
			const gain = ctx.createGain();
			osc.type = "sine";
			osc.frequency.setValueAtTime(587.33, ctx.currentTime);
			osc.frequency.exponentialRampToValueAtTime(880, ctx.currentTime + .08);
			gain.gain.setValueAtTime(.12, ctx.currentTime);
			gain.gain.exponentialRampToValueAtTime(.001, ctx.currentTime + .12);
			osc.connect(gain);
			gain.connect(ctx.destination);
			osc.start();
			osc.stop(ctx.currentTime + .12);
		} catch {}
	}
	playMessageReceived() {
		try {
			const ctx = this.getContext();
			if (!ctx) return;
			const osc1 = ctx.createOscillator();
			const osc2 = ctx.createOscillator();
			const gain = ctx.createGain();
			osc1.type = "sine";
			osc2.type = "sine";
			osc1.frequency.setValueAtTime(659.25, ctx.currentTime);
			osc2.frequency.setValueAtTime(1046.5, ctx.currentTime + .08);
			gain.gain.setValueAtTime(.15, ctx.currentTime);
			gain.gain.exponentialRampToValueAtTime(.001, ctx.currentTime + .25);
			osc1.connect(gain);
			osc2.connect(gain);
			gain.connect(ctx.destination);
			osc1.start(ctx.currentTime);
			osc1.stop(ctx.currentTime + .08);
			osc2.start(ctx.currentTime + .08);
			osc2.stop(ctx.currentTime + .25);
		} catch {}
	}
	playCallRingtone() {
		try {
			const ctx = this.getContext();
			if (!ctx) return;
			const osc1 = ctx.createOscillator();
			const osc2 = ctx.createOscillator();
			const gain = ctx.createGain();
			osc1.type = "sine";
			osc2.type = "sine";
			osc1.frequency.value = 440;
			osc2.frequency.value = 480;
			gain.gain.setValueAtTime(.1, ctx.currentTime);
			gain.gain.exponentialRampToValueAtTime(.001, ctx.currentTime + 1.2);
			osc1.connect(gain);
			osc2.connect(gain);
			gain.connect(ctx.destination);
			osc1.start();
			osc2.start();
			osc1.stop(ctx.currentTime + 1.2);
			osc2.stop(ctx.currentTime + 1.2);
		} catch {}
	}
	playBeep() {
		try {
			const ctx = this.getContext();
			if (!ctx) return;
			const osc = ctx.createOscillator();
			const gain = ctx.createGain();
			osc.type = "sine";
			osc.frequency.value = 520;
			gain.gain.setValueAtTime(.08, ctx.currentTime);
			gain.gain.exponentialRampToValueAtTime(.001, ctx.currentTime + .1);
			osc.connect(gain);
			gain.connect(ctx.destination);
			osc.start();
			osc.stop(ctx.currentTime + .1);
		} catch {}
	}
};
